const msg = $json.message || {};
const cq = $json.callback_query || null;

// اگه یه روز خواستی چند نفر دیگه هم بتونن سفارش‌ها رو تایید/رد کنن، آی‌دی‌شون رو هم اینجا اضافه کن
const adminChatId = "6452519019";

let kind = "free_text";
let chatId, username, firstName, text;
let slug = null;
let decisionAction = null;
let decisionOrderId = null;

if (cq) {
  // دکمه‌ی تایید/رد زیر عکس رسید فشرده شده
  chatId = cq.from?.id;
  username = cq.from?.username || "";
  firstName = cq.from?.first_name || "";
  text = "";
  const m = (cq.data || "").match(/^(approve|reject):(ORDER-\S+)$/);
  if (String(chatId) === adminChatId && m) {
    kind = "admin_decision";
    decisionAction = m[1];
    decisionOrderId = m[2];
  } else if (String(chatId) === adminChatId && cq.data === "admin:report") {
    kind = "admin_report";
  }
} else {
  chatId = msg.chat?.id;
  username = msg.from?.username || "";
  firstName = msg.from?.first_name || "";
  text = (msg.text || "").trim();

  if (msg.contact) {
    kind = "contact";
  } else if (String(chatId) === adminChatId && text === "/start") {
    // ادمین وارد مسیر عادی مشتری (درخواست شماره و ...) نمی‌شه، منوی خودش رو می‌بینه
    kind = "admin_menu";
  } else if (/^\/start\s+\S+/.test(text)) {
    kind = "start_product";
    slug = text.match(/^\/start\s+(\S+)/)[1];
  } else if (text === "/start") {
    kind = "start_product";
    slug = null;
  } else if (msg.photo && msg.photo.length) {
    kind = "photo_receipt";
  } else if (String(chatId) === adminChatId && /^(تایید|رد)\s+(ORDER-\S+)/.test(text)) {
    kind = "admin_decision";
    const m2 = text.match(/^(تایید|رد)\s+(ORDER-\S+)/);
    decisionAction = m2[1] === "تایید" ? "approve" : "reject";
    decisionOrderId = m2[2];
  }
}

const photo = msg.photo ? msg.photo[msg.photo.length - 1] : null;
const phone = msg.contact ? msg.contact.phone_number : null;

return [{
  json: {
    kind, chatId, username, firstName, text, slug,
    decisionAction, decisionOrderId,
    photoFileId: photo ? photo.file_id : null,
    phone,
  },
}];

const t = $json;
return [{
  json: {
    telegram_user_id: t.chatId,
    username: t.username,
    phone: t.phone,
    created_at: new Date().toISOString(),
  },
}];

