const rows = $input.all().map((i) => i.json);
const now = Date.now();
const threeDaysMs = 3 * 24 * 60 * 60 * 1000;

const pendingReview = rows.filter((o) => o.status === 'pending_review').length;
const awaitingPayment = rows.filter((o) => o.status === 'awaiting_payment').length;
const deliveredThisMonth = rows.filter((o) => {
  if (o.status !== 'delivered' || !o.reviewed_at) return false;
  const d = new Date(o.reviewed_at);
  const n = new Date();
  return d.getFullYear() === n.getFullYear() && d.getMonth() === n.getMonth();
}).length;
const expiringSoon = rows.filter((o) => {
  if (o.status !== 'delivered' || !o.expires_at) return false;
  const diff = new Date(o.expires_at).getTime() - now;
  return diff > 0 && diff <= threeDaysMs;
}).length;

return [{
  json: {
    chatId: $('تشخیص نوع پیام').first().json.chatId,
    pendingReview, awaitingPayment, deliveredThisMonth, expiringSoon,
  },
}];

