parameters.jsCode:
// اگه یه ردیف (سفارش/لایسنس/مشتری) به هر دلیلی (مثلاً چندبار زدن دکمه‌ی تایید روی یک سفارش)
// توی شیت تکراری ثبت شده باشه، اینجا با کلید یکتاش یک‌بار نگه داشته می‌شه تا گزارش تکراری نشه —
// این فقط نمایش رو تمیز می‌کنه؛ خودِ شیت اصلاح نمی‌شه.
function dedupeBy(rows, keyFn) {
  const seen = new Set();
  const out = [];
  for (const row of rows) {
    const key = keyFn(row);
    if (key && seen.has(key)) continue;
    if (key) seen.add(key);
    out.push(row);
  }
  return out;
}

const customersRaw = dedupeBy(
  $('خواندن مشتریان (گزارش)').all().map((i) => i.json),
  (c) => c.telegram_user_id
);
const orders = dedupeBy(
  $('خواندن سفارش‌ها (گزارش)').all().map((i) => i.json),
  (o) => o.order_id
);
const licenses = dedupeBy(
  $('خواندن لایسنس‌ها (گزارش)').all().map((i) => i.json),
  (l) => l.license_key
);

const customers = customersRaw
  .map((c) => {
    let chatHistory = [];
    try {
      chatHistory = JSON.parse(c.chat_history || '[]');
    } catch (e) {
      chatHistory = [];
    }
    if (!Array.isArray(chatHistory)) chatHistory = [];
    return {
      chatId: c.telegram_user_id,
      username: c.username || '',
      phone: c.phone || '',
      pendingState: c.pending_state || '',
      createdAt: c.created_at || '',
      chatHistory,
      orders: orders.filter((o) => String(o.telegram_user_id) === String(c.telegram_user_id)),
      licenses: licenses.filter((l) => String(l.telegram_user_id) === String(c.telegram_user_id)),
    };
  })
  .filter((c) => c.chatId)
  .sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());

const now = Date.now();
const threeDaysMs = 3 * 24 * 60 * 60 * 1000;
const stats = {
  pendingReview: orders.filter((o) => o.status === 'pending_review').length,
  awaitingPayment: orders.filter((o) => o.status === 'awaiting_payment').length,
  deliveredThisMonth: orders.filter((o) => {
    if (o.status !== 'delivered' || !o.reviewed_at) return false;
    const d = new Date(o.reviewed_at);
    const n = new Date();
    return d.getFullYear() === n.getFullYear() && d.getMonth() === n.getMonth();
  }).length,
  expiringSoon: orders.filter((o) => {
    if (o.status !== 'delivered' || !o.expires_at) return false;
    const diff = new Date(o.expires_at).getTime() - now;
    return diff > 0 && diff <= threeDaysMs;
  }).length,
};

const STATUS_LABELS = {
  awaiting_requirements: 'در انتظار توضیح نیاز',
  awaiting_payment: 'در انتظار پرداخت',
  pending_review: 'در انتظار تایید',
  delivered: 'تحویل‌شده',
  rejected: 'رد شده',
};

function esc(s) {
  return String(s == null ? '' : s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function money(n) {
  return Number(n || 0).toLocaleString('fa-IR');
}

function customerBlock(c) {
  const statusKey = (c.pendingState || '').split(':')[0];
  const statusLabel = STATUS_LABELS[statusKey] || c.pendingState || '';
  const statusChip = statusLabel
    ? `<span class="chip">${esc(statusLabel)}</span>`
    : '';

  const chatHtml = c.chatHistory.length
    ? c.chatHistory
        .map(
          (m) =>
            `<div class="msg ${m.role === 'user' ? 'msg-user' : 'msg-bot'}">${esc(m.content)}</div>`
        )
        .join('')
    : '<p class="muted">هنوز گفتگوی آزادی با AI نداشته.</p>';

  const ordersHtml = c.orders.length
    ? `<div class="rows">${c.orders
        .map(
          (o) => `<div class="row">
            <span class="mono">${esc(o.order_id)}</span>
            <span>${esc(o.product_slug)}</span>
            <span>${money(o.amount)} تومان</span>
            <span class="chip">${esc(STATUS_LABELS[o.status] || o.status)}</span>
          </div>`
        )
        .join('')}</div>`
    : '';

  const licensesHtml = c.licenses.length
    ? `<div class="rows">${c.licenses
        .map(
          (l) => `<div class="row">
            <span class="mono cyan">${esc(l.license_key)}</span>
            <span class="muted">${l.expires_at ? new Date(l.expires_at).toLocaleDateString('fa-IR') : '—'}</span>
          </div>`
        )
        .join('')}</div>`
    : '';

  return `<details class="customer">
    <summary>
      <span class="who">
        <b>${c.username ? '@' + esc(c.username) : 'بدون یوزرنیم'}</b>
        <span class="mono muted">${esc(c.phone) || '—'}</span>
      </span>
      <span class="meta">${statusChip}<span class="muted">${c.orders.length} سفارش</span></span>
    </summary>
    <div class="customer-body">
      <h4>گفتگوی هوش مصنوعی فروش</h4>
      ${chatHtml}
      ${c.orders.length ? '<h4>سفارش‌ها</h4>' + ordersHtml : ''}
      ${c.licenses.length ? '<h4>لایسنس‌ها</h4>' + licensesHtml : ''}
    </div>
  </details>`;
}

const generatedAt = new Date().toLocaleString('fa-IR', { dateStyle: 'full', timeStyle: 'short' });

const html = `<!doctype html>
<html lang="fa" dir="rtl">
<head>
<meta charset="utf-8" />
<title>گزارش مشتری‌ها — IR-CLU</title>
<meta name="viewport" content="width=device-width, initial-scale=1" />
<style>
  :root {
    --ink:#07080d; --surface:#10131c; --surface2:#161b28; --border:rgba(230,234,245,.1);
    --text:#e8eaf2; --muted:#8b93a8; --cyan:#34d9e8; --violet:#9b7bf8; --ember:#fb7a3c;
  }
  * { box-sizing: border-box; }
  body { margin:0; background:var(--ink); color:var(--text); font-family:"Vazirmatn","Segoe UI",Tahoma,sans-serif; line-height:1.8; }
  .wrap { max-width:860px; margin:0 auto; padding:40px 20px 80px; }
  h1 { font-size:26px; margin:0; }
  .gen { font-family:monospace; font-size:12px; color:var(--muted); margin-top:10px; }
  .stats { display:grid; grid-template-columns:repeat(auto-fit,minmax(150px,1fr)); gap:12px; margin:28px 0; }
  .stat { background:var(--surface); border:1px solid var(--border); border-radius:14px; padding:16px 18px; }
  .stat b { font-size:22px; display:block; }
  .stat span { font-size:12px; color:var(--muted); }
  .customer { background:var(--surface); border:1px solid var(--border); border-radius:14px; margin-bottom:10px; overflow:hidden; }
  .customer summary { cursor:pointer; list-style:none; padding:16px 18px; display:flex; align-items:center; justify-content:space-between; gap:10px; flex-wrap:wrap; }
  .customer summary::-webkit-details-marker { display:none; }
  .who { display:flex; flex-direction:column; gap:4px; }
  .meta { display:flex; align-items:center; gap:10px; font-size:12px; }
  .chip { border:1px solid rgba(52,217,232,.4); color:var(--cyan); border-radius:999px; padding:2px 10px; font-size:11px; }
  .customer-body { border-top:1px solid var(--border); padding:16px 18px; }
  .customer-body h4 { font-size:12px; text-transform:uppercase; letter-spacing:.05em; color:var(--muted); margin:16px 0 8px; }
  .customer-body h4:first-child { margin-top:0; }
  .msg { max-width:85%; border-radius:14px; padding:9px 14px; margin:6px 0; font-size:14px; }
  .msg-user { background:var(--surface2); }
  .msg-bot { background:linear-gradient(90deg,var(--cyan),var(--violet)); color:var(--ink); margin-inline-start:auto; }
  .rows { display:flex; flex-direction:column; gap:6px; }
  .row { display:flex; flex-wrap:wrap; gap:10px; align-items:center; justify-content:space-between; border:1px solid var(--border); border-radius:10px; padding:8px 12px; font-size:13px; }
  .mono { font-family:monospace; direction:ltr; unicode-bidi:isolate; }
  .cyan { color:var(--cyan); }
  .muted { color:var(--muted); }
</style>
</head>
<body>
<div class="wrap">
  <h1>گزارش مشتری‌ها و گفتگوهاشون با ربات فروش</h1>
  <div class="gen">تولید شده در: ${esc(generatedAt)}</div>

  <div class="stats">
    <div class="stat"><b>${stats.pendingReview}</b><span>در انتظار تایید رسید</span></div>
    <div class="stat"><b>${stats.awaitingPayment}</b><span>منتظر پرداخت مشتری</span></div>
    <div class="stat"><b>${stats.deliveredThisMonth}</b><span>تحویل‌شده این ماه</span></div>
    <div class="stat"><b>${stats.expiringSoon}</b><span>رو‌به‌انقضا (۳ روز آینده)</span></div>
  </div>

  ${customers.length ? customers.map(customerBlock).join('') : '<p class="muted">هنوز هیچ مشتری‌ای ثبت نشده.</p>'}
</div>
</body>
</html>`;

const buffer = Buffer.from(html, 'utf8');

return [{
  json: { generatedAt },
  binary: {
    data: {
      data: buffer.toString('base64'),
      mimeType: 'text/html',
      fileName: `irclu-report-${Date.now()}.html`,
    },
  },
}];
